import RNA
target = '((((....))...))'
# Try: outer strong GC, inner GC, loop GAAA, linker AAA.
# Hmm but inner stem (2,9)(3,8) not forming consistently when loop is 4 and linker 3.
# Let me try with different loop motifs to find one that allows inner stem to close.
import itertools
bases='ACGU'
# Fix pairs as GC: pos0=C,pos14=G; pos1=C,pos13=G; pos2=C,pos9=G; pos3=C,pos8=G (all C-G)
# loop 4-7, linker 10-12
best=[]
for l1 in 'GUAC':
    for l2 in 'UACG':
        for l3 in 'ACGU':
            for l4 in 'CGUA':
                loop=l1+l2+l3+l4
                for k1 in 'AUGC':
                    for k2 in 'AUCG':
                        for k3 in 'AUGC':
                            seq='CCCG'+loop+'G'+k1+k2+k3+'GGG'
                            f=RNA.fold(seq)
                            if f[0]==target:
                                best.append((seq,f[1]))
print('found',len(best))
for s in best[:10]: print(s)
"

