import RNA
target='((((....))...))'
# Build a constraint-minimize sequence: use sc_MINIMIZE approach via fold_compound.sc_minimize?
# Actually ViennaRNA has 'sc_minimize' to find min across sequences? No. Use DIRECT: RNA.fold_compound + minimization is structure-based not sequence-based.
# Try 'RNA.opt_pf_ss' or similar. Let's just try a brute force on the inner stem problem.
# Actually test: is the issue that 'inner stem 2,9 +3,8 + outer 0,14 +1,13' has too short a stem with a 3-nt linker that the linker pairs?
import itertools
best=None; bestscore=99
# enumerate loop=4 fixed GAAA, linker 3 varied, outer/inner pair combos all 4 pair types
pairs=[('C','G'),('G','C'),('A','U'),('U','A')]
cnt=0
for o1 in pairs:
    for o2 in pairs:
        for i1 in pairs:
            for i2 in pairs:
                for l1 in ['GAAA','UUCG','CUUG','GCAA','AAAA','UUUU']:
                    for k in itertools.product('ACGU',repeat=3):
                        seq=o1[0]+o2[0]+i1[0]+i2[0]+l1+i2[1]+i1[1]+''.join(k)+o2[1]+o1[1]
                        if len(seq)!=15: continue
                        f=RNA.fold(seq)
                        d=RNA.bp_distance(f[0],target)
                        if d==0:
                            print('SOLVED',seq,f[0]); 
                            cnt+=1
                            if cnt>5: exit()
print('cnt',cnt)
"

